from pathlib import Path
import json,hashlib
root=Path.cwd()
def item(path):
 p=root/path
 return {'path':path,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
building=item('validation/market-street-s2d/market-street-optimized.glb')
records={'phase':'R0-RESET-FINAL','reuseOnly':True,'runtimeOmissions':['Detached C1 fountain caption only; approved sculpture and basin geometry retained; source GLB unchanged'],'downloadedAssets':0,'approvedBuildingGLB':building,'buildingGroups':['B1_Kopi_Awan001','B2_Lembaran_Shophouse001','B3_Rupa_Rimba_Atelier001','B4_Serambi_Corner_Shop001'],'approvedCivicSource':item('validation/town-square-r0c1a/town-square-design.blend'),'independentNativeDerivative':item('validation/reset-final/civic-reuse.blend'),'exports':[item('validation/reset-final/'+n+'.glb')for n in ['fountain','pavilion','bench','cafe-set']],'process':'Actual Blender MCP: independent native copy, selected existing civic components, origin normalization, mesh conversion and join by component, glTF export. No original master was saved or overwritten. Runtime batches only compatible static material groups.','rights':[{'component':'Four storefronts','terms':'Original AR(N)AN work plus existing CC0-1.0 Kenney detailed window and Quaternius fern components. No new license inferred.','record':'docs/urban-atlas/market-street-s2c/ASSET-RECORD.md'},{'component':'Fountain, pavilion, bench, cafe set','terms':'Original project geometry authored in C1A; inherited source rights retained.','record':'docs/urban-atlas/town-square-r0c1a/ASSET-RECORD.md'},{'component':'Existing landscape','terms':'Preserved project geometry and previously verified Quaternius CC0 sources. Instance positions are a reversible scene derivative only.','record':'ASSET_MANIFEST.md'},{'component':'Civic paving, arrival guard, physical reservation noticeboard','terms':'Small original project interface details. No third-party images, fonts, models or assets downloaded. Browser/system text is used on the physical sign.'}],'reference':'Original concept boards already available in validation/asset-selection-s1/references/; used for composition, not as screenshot evidence.'}
(root/'validation/reset-final/provenance.json').write_text(json.dumps(records,indent=2)+'\n')
